def profile_value(profile: list[dict[str, Any]], day: int) -> float:
    if not profile:
        return 0.0
    step_candidates: list[tuple[int, float]] = []
    for p in profile:
        if not isinstance(p, dict):
            continue
        ptype = str(p.get("type", "constant"))
        repeat_period_days = int(to_float(p.get("repeat_period_days"), 0.0))
        eval_day = day
        if repeat_period_days > 0:
            eval_day = day % repeat_period_days
        if ptype == "constant":
            return to_float(p.get("value"), 0.0)
        if ptype == "step":
            start = int(to_float(p.get("start_day"), 0.0))
            val = to_float(p.get("value"), 0.0)
            if eval_day >= start:
                step_candidates.append((start, val))
        if ptype == "piecewise":
            points = p.get("points") or []
            for pt in points:
                if not isinstance(pt, dict):
                    continue
                t = int(to_float(pt.get("t"), -1))
                v = to_float(pt.get("value"), 0.0)
                if eval_day >= t >= 0:
                    step_candidates.append((t, v))
    if step_candidates:
        step_candidates.sort(key=lambda x: x[0])
        return step_candidates[-1][1]
    return 0.0


def _cached_profile_value(
    profile: list[dict[str, Any]],
    day: int,
    value_cache: dict[tuple[int, int], float],
) -> float:
    # The owning run retains its profiles unchanged for the cache's lifetime.
    # Identity keeps distinct profiles separate, even when their days coincide.
    key = (id(profile), day)
    try:
        return value_cache[key]
    except KeyError:
        value = profile_value(profile, day)
        value_cache[key] = value
        return value


def profile_window_average(
    profile: list[dict[str, Any]],
    day: int,
    window_days: int,
    *,
    value_cache: dict[tuple[int, int], float] | None = None,
) -> float:
    """Average days in order; an optional cache belongs to one run's fixed profiles."""
    window_days = max(1, int(window_days))
    if value_cache is not None:
        if window_days <= 1:
            return _cached_profile_value(profile, day, value_cache)
        # Keep the same ordered sum as the uncached evaluator: prefix sums or
        # rolling sums can change floating-point results and physical decisions.
        return sum(
            _cached_profile_value(profile, day + offset, value_cache)
            for offset in range(window_days)
        ) / float(window_days)
    if window_days <= 1:
        return profile_value(profile, day)
    return sum(profile_value(profile, day + offset) for offset in range(window_days)) / float(window_days)


def demand_targets_for_day(
    demand_profiles: dict[tuple[str, str], list[dict[str, Any]]],
    day: int,
    *,
    window_days: int = 1,
    value_cache: dict[tuple[int, int], float] | None = None,
) -> dict[tuple[str, str], float]:
    return {
        pair: max(0.0, profile_window_average(profile, day, window_days, value_cache=value_cache))
        for pair, profile in demand_profiles.items()
    }


def choose_scenario(data: dict[str, Any], scenario_id: str) -> dict[str, Any]:
    scenarios = data.get("scenarios", []) or []
    for scn in scenarios:
        if str(scn.get("id")) == scenario_id:
            return scn
    raise ValueError(f"Unknown scenario: {scenario_id!r}")


def lane_records(
    edges: list[dict[str, Any]],
    economic_policy: dict[str, float] | None = None,
    *,
    mrp_multisource_policy: str = "legacy",
) -> tuple[list[dict[str, Any]], dict[tuple[str, str], list[dict[str, Any]]]]:
    economic_policy = economic_policy or {}
    transport_floor = max(0.0, to_float(economic_policy.get("transport_cost_floor_per_unit"), 0.02))
    transport_per_km = max(0.0, to_float(economic_policy.get("transport_cost_per_km_per_unit"), 0.00008))
    purchase_floor = max(0.0, to_float(economic_policy.get("purchase_cost_floor_per_unit"), 0.01))
    transport_realism_multiplier = max(0.1, to_float(economic_policy.get("transport_cost_realism_multiplier"), 1.0))
    purchase_realism_multiplier = max(0.1, to_float(economic_policy.get("purchase_cost_realism_multiplier"), 1.0))
    lanes: list[dict[str, Any]] = []
    lanes_by_dest_item: dict[tuple[str, str], list[dict[str, Any]]] = defaultdict(list)
    for e in edges:
        src = str(e.get("from"))
        dst = str(e.get("to"))
        lead = e.get("lead_time") or {}
        lead_days = int(round(max(1.0, to_float((lead or {}).get("mean"), 1.0))))
        lead_days_mean = max(1.0, to_float((lead or {}).get("mean"), 1.0))
        lead_stages = int(round(max(1.0, to_float((lead or {}).get("stages"), 1.0))))
        lead_time_type = str((lead or {}).get("type", "constant"))
        distance_km = max(0.0, to_float(e.get("distance_km"), 0.0))
        tc = e.get("transport_cost") or {}
        explicit_transport_cost = max(0.0, to_float((tc or {}).get("value"), 0.0))
        fallback_transport_cost = max(transport_floor, distance_km * transport_per_km)
        # Most transport flows have a default 0 transport_cost, so force a realistic floor by distance.
        cost = (explicit_transport_cost if explicit_transport_cost > 0 else fallback_transport_cost) * transport_realism_multiplier
        ot = e.get("order_terms") or {}
        sell_price = to_float((ot or {}).get("sell_price"), 0.0)
        price_base = to_float((ot or {}).get("price_base"), 1.0)
        if price_base <= 0:
            price_base = 1.0
        priced_unit_purchase_cost = max(0.0, sell_price / price_base)
        if priced_unit_purchase_cost > 0.0 and not bool((ot or {}).get("is_default")):
            unit_purchase_cost = priced_unit_purchase_cost * purchase_realism_multiplier
            purchase_cost_is_fallback = False
        else:
            unit_purchase_cost = max(purchase_floor, priced_unit_purchase_cost) * purchase_realism_multiplier
            purchase_cost_is_fallback = True
        order_unit = normalize_unit((ot or {}).get("quantity_unit"))
        attrs = e.get("attrs") or {}
        standard_order_qty_raw = max(0.0, to_float(attrs.get("standard_order_qty"), 0.0))
        standard_order_uom = normalize_unit(attrs.get("standard_order_uom") or order_unit)
        if standard_order_qty_raw > 0 and can_convert_units(standard_order_uom, order_unit):
            standard_order_qty = convert_quantity(standard_order_qty_raw, standard_order_uom, order_unit)
        else:
            standard_order_qty = standard_order_qty_raw
        service_level = e.get("service_level") or {}
        reliability = to_float(
            service_level.get("otif", e.get("otif", 1.0)),
            1.0,
        )
        if "otif" in service_level:
            reliability_source = "service_level.otif"
        elif "otif" in e:
            reliability_source = "edge.otif"
        else:
            reliability_source = "default_1.0"
        reliability = max(0.01, min(1.0, reliability))
        supply_order_frequency = (ot.get("supply_order_frequency") or {})
        order_frequency_days = int(
            round(max(1.0, to_float((supply_order_frequency or {}).get("value"), 1.0)))
        )
        delay_step_limit = int(round(max(1.0, to_float(((e.get("delay_step_limit") or {}).get("value")), 999.0))))
        base_standard_order_qty = standard_order_qty
        base_order_frequency_days = order_frequency_days
        for item_id in (e.get("items") or []):
            standard_order_qty = base_standard_order_qty
            order_frequency_days = base_order_frequency_days
            standard_order_qty_note = ""
            lane_order_uom = order_unit or standard_order_uom
            canonical_decision = None
            dispatch_decision = None
            if lane_order_uom in {"G", "KG", "UN", "M"}:
                canonical_decision = resolve_canonical_lane_lot(
                    origin_id=src,
                    destination_id=dst,
                    item_id=item_id,
                    lane_uom=lane_order_uom,
                )
                dispatch_decision = resolve_internal_dispatch_multiple(
                    origin_id=src,
                    destination_id=dst,
                    item_id=item_id,
                    lane_uom=lane_order_uom,
                )
            if canonical_decision is not None:
                previous_qty = standard_order_qty
                standard_order_qty = max(0.0, canonical_decision.quantity)
                if canonical_decision.order_frequency_days is not None:
                    order_frequency_days = max(
                        1,
                        int(canonical_decision.order_frequency_days),
                    )
                standard_order_qty_note = (
                    f"canonical {canonical_decision.scope}: {previous_qty:g} -> "
                    f"{standard_order_qty:g} {canonical_decision.uom}; "
                    f"source={canonical_decision.source}; "
                    f"confidence={canonical_decision.confidence}"
                )
            override = standard_order_override(src, dst, item_id)
            if (
                override
                and standard_order_qty >= max(0.0, to_float(override.get("min_original_qty"), 0.0))
                and (
                    not override.get("uom")
                    or normalize_unit(override.get("uom")) == (order_unit or standard_order_uom)
                )
            ):
                previous_qty = standard_order_qty
                standard_order_qty = max(0.0, to_float(override.get("qty"), standard_order_qty))
                if "order_frequency_days" in override:
                    order_frequency_days = max(
                        1,
                        int(round(max(1.0, to_float(override.get("order_frequency_days"), order_frequency_days)))),
                    )
                standard_order_qty_note = str(
                    override.get("note")
                    or f"overridden from {previous_qty:g} to {standard_order_qty:g}"
                )
            lane = {
                "edge_id": str(e.get("id")),
                "src": src,
                "dst": dst,
                "item_id": str(item_id),
                "lead_days": lead_days,
                "lead_days_mean": lead_days_mean,
                "lead_stages": lead_stages,
                "lead_time_type": lead_time_type,
                "lead_time_source": str((lead or {}).get("source") or ""),
                "lead_time_is_default": bool((lead or {}).get("is_default")),
                "order_frequency_days": order_frequency_days,
                "delay_step_limit": delay_step_limit,
                "unit_transport_cost": cost,
                "transport_cost_basis": str(tc.get("per") or "unit").strip().lower(),
                "transport_tariff_batch_qty": tc.get("batch_qty"),
                "unit_purchase_cost": unit_purchase_cost,
                "raw_purchase_cost": priced_unit_purchase_cost,
                "purchase_cost_is_fallback": purchase_cost_is_fallback,
                "raw_transport_cost": explicit_transport_cost,
                "transport_cost_is_fallback": explicit_transport_cost <= 0,
                "reliability": reliability,
                "reliability_source": reliability_source,
                "availability_profile": e.get("availability_profile") or [],
                "standard_order_qty": standard_order_qty,
                "standard_order_uom": lane_order_uom,
                "standard_order_qty_note": standard_order_qty_note,
                "standard_order_policy_scope": (
                    canonical_decision.scope if canonical_decision else ""
                ),
                "standard_order_policy_source": (
                    canonical_decision.source if canonical_decision else ""
                ),
                "standard_order_policy_confidence": (
                    canonical_decision.confidence if canonical_decision else ""
                ),
                "physical_dispatch_multiple": (
                    max(0.0, dispatch_decision.quantity)
                    if dispatch_decision
                    else 0.0
                ),
                "physical_dispatch_uom": (
                    dispatch_decision.uom if dispatch_decision else ""
                ),
                "physical_dispatch_policy_scope": (
                    dispatch_decision.scope if dispatch_decision else ""
                ),
                "physical_dispatch_policy_source": (
                    dispatch_decision.source if dispatch_decision else ""
                ),
                "physical_dispatch_policy_confidence": (
                    dispatch_decision.confidence if dispatch_decision else ""
                ),
            }
            lanes.append(lane)
            lanes_by_dest_item[(dst, str(item_id))].append(lane)

    def normalized_penalties(values: list[float]) -> list[float]:
        if not values:
            return []
        low = min(values)
        high = max(values)
        if high - low <= 1e-9:
            return [0.0 for _ in values]
        return [(value - low) / (high - low) for value in values]

    def mrp_split_shares(count: int) -> list[float]:
        if count <= 0:
            return []
        if count == 1:
            return [1.0]
        if mrp_multisource_policy == "portfolio_annual_min_lot":
            if count == 2:
                return [0.8, 0.2]
            if count == 3:
                return [0.7, 0.2, 0.1]
            if count == 4:
                return [0.7, 0.2, 0.05, 0.05]
            tail = 0.1 / float(count - 2)
            return [0.7, 0.2] + [tail] * (count - 2)
        if count == 2:
            return [0.7, 0.3]
        if count == 3:
            return [0.7, 0.2, 0.1]
        tail = 0.1 / float(count - 2)
        return [0.7, 0.2] + [tail] * (count - 2)

    def assign_cost_risk_shares(values: list[dict[str, Any]]) -> None:
        if not values:
            return
        if len(values) == 1:
            lane = values[0]
            lane["mrp_share"] = 1.0
            lane["mrp_rank"] = 1
            lane["mrp_share_basis"] = "single_source"
            lane["mrp_landed_unit_cost"] = max(0.0, to_float(lane.get("unit_purchase_cost"), 0.0)) + max(
                0.0,
                to_float(lane.get("unit_transport_cost"), 0.0),
            )
            lane["mrp_cost_penalty"] = 0.0
            lane["mrp_lead_penalty"] = 0.0
            lane["mrp_reliability_penalty"] = 0.0
            lane["mrp_variability_penalty"] = 0.0
            lane["mrp_allocation_penalty"] = 0.0
            return

        landed_costs = [
            max(0.0, to_float(lane.get("unit_purchase_cost"), 0.0))
            + max(0.0, to_float(lane.get("unit_transport_cost"), 0.0))
            for lane in values
        ]
        lead_refs = [float(lead_time_reference_days(lane)) for lane in values]
        lead_covers = [float(lead_time_cover_days(lane, True, "industrial")) for lane in values]
        reliability_penalties = [max(0.0, 1.0 - max(0.01, min(1.0, to_float(lane.get("reliability"), 1.0)))) for lane in values]
        variability_raw = [
            max(0.0, cover / max(1.0, ref) - 1.0)
            for cover, ref in zip(lead_covers, lead_refs)
        ]

        cost_penalties = normalized_penalties(landed_costs)
        lead_penalties = normalized_penalties(lead_refs)
        variability_penalties = normalized_penalties(variability_raw)
        reliability_norm = normalized_penalties(reliability_penalties)
        allocation_penalties: list[float] = []
        desirabilities: list[float] = []
        for cost_penalty, lead_penalty, rel_penalty, var_penalty in zip(
            cost_penalties,
            lead_penalties,
            reliability_norm,
            variability_penalties,
        ):
            alea_penalty = (0.65 * rel_penalty) + (0.35 * var_penalty)
            penalty = (0.60 * cost_penalty) + (0.25 * lead_penalty) + (0.15 * alea_penalty)
            allocation_penalties.append(penalty)
            desirabilities.append(math.exp(-3.0 * penalty))

        desirability_total = sum(desirabilities)
        if desirability_total <= 1e-12:
            shares = [1.0 / float(len(values)) for _ in values]
        else:
            shares = [desirability / desirability_total for desirability in desirabilities]

        for lane, share, landed_cost, cost_penalty, lead_penalty, rel_penalty, var_penalty, penalty in zip(
            values,
            shares,
            landed_costs,
            cost_penalties,
            lead_penalties,
            reliability_norm,
            variability_penalties,
            allocation_penalties,
        ):
            lane["mrp_share"] = share
            lane["mrp_share_basis"] = "cost_60_lead_25_reliability_variability_15"
            lane["mrp_landed_unit_cost"] = landed_cost
            lane["mrp_cost_penalty"] = cost_penalty
            lane["mrp_lead_penalty"] = lead_penalty
            lane["mrp_reliability_penalty"] = rel_penalty
            lane["mrp_variability_penalty"] = var_penalty
            lane["mrp_allocation_penalty"] = penalty
        values.sort(
            key=lambda lane: (
                max(0.0, to_float(lane.get("mrp_allocation_penalty"), 0.0)),
                max(0.0, to_float(lane.get("mrp_landed_unit_cost"), 0.0)),
                max(1, int(to_float(lane.get("lead_days"), 1.0))),
                str(lane.get("src") or ""),
            )
        )
        for rank, lane in enumerate(values, start=1):
            lane["mrp_rank"] = rank

    for key, values in lanes_by_dest_item.items():
        values.sort(key=lambda x: (x["unit_transport_cost"], x["lead_days"], x["src"]))
        if mrp_multisource_policy == "portfolio_cost_risk":
            assign_cost_risk_shares(values)
        else:
            shares = mrp_split_shares(len(values))
            share_basis = (
                "portfolio_fixed_split_with_annual_min_lot"
                if mrp_multisource_policy == "portfolio_annual_min_lot" and len(values) > 1
                else "legacy_fixed_split"
            )
            for rank, (lane, share) in enumerate(zip(values, shares), start=1):
                lane["mrp_share"] = share
                lane["mrp_rank"] = rank
                lane["mrp_share_basis"] = share_basis
                lane["mrp_landed_unit_cost"] = max(0.0, to_float(lane.get("unit_purchase_cost"), 0.0)) + max(
                    0.0,
                    to_float(lane.get("unit_transport_cost"), 0.0),
                )
                lane["mrp_cost_penalty"] = 0.0
                lane["mrp_lead_penalty"] = 0.0
                lane["mrp_reliability_penalty"] = 0.0
                lane["mrp_variability_penalty"] = 0.0
                lane["mrp_allocation_penalty"] = 0.0
        lanes_by_dest_item[key] = values
    return lanes, lanes_by_dest_item


def node_review_period_days(node: dict[str, Any], default: int = 7) -> int:
    sim_policy = ((node.get("policies") or {}).get("simulation_policy") or {})
    return int(round(max(1.0, to_float(sim_policy.get("review_period_days"), float(default)))))


def process_output_capacity_by_item(
    node: dict[str, Any],
    item_unit_map: dict[str, str],
) -> dict[str, float]:
    out: dict[str, float] = defaultdict(float)
    for proc in (node.get("processes") or []):
        cap = max(0.0, to_float(((proc.get("capacity") or {}).get("max_rate")), 0.0))
        if cap <= 0:
            continue
        for output in (proc.get("outputs") or []):
            item_id = str(output.get("item_id") or "")
            if not item_id:
                continue
            output_uom = str(output.get("uom") or "")
            output_unit = normalize_unit(output_uom.split("/", 1)[0] if "/" in output_uom else output_uom)
            item_unit = normalize_unit(item_unit_map.get(item_id, output_unit))
            value = cap
            if output_unit and item_unit and can_convert_units(output_unit, item_unit):
                value = convert_quantity(cap, output_unit, item_unit)
            out[item_id] += max(0.0, value)
    return dict(out)


def lane_availability_multiplier(lane: dict[str, Any], day: int) -> float:
    mult = 1.0
    for window in lane.get("availability_profile") or []:
        if not isinstance(window, dict):
            continue
        start = int(round(to_float(window.get("start_day"), 0.0)))
        end = int(round(to_float(window.get("end_day"), start)))
        if start <= day <= end:
            mult *= max(0.0, to_float(window.get("multiplier"), 1.0))
    return max(0.0, mult)


def normalize_lead_time_distribution_mode(value: Any) -> str:
    mode = str(value or "erlang").strip().lower().replace("-", "_")
    if mode in {"industrial", "industrial_right_tail", "industrial_realistic"}:
        return "industrial"
    return "erlang"


def industrial_lead_cover_days(mean: float) -> int:
    # Industrial approximation: nominal lead time plus a moderate planning buffer.
    # Safety time/stock is modelled separately, so this should not be an extreme p95.
    fixed_buffer = 1.0 if mean <= 5.0 else 2.0
    return int(math.ceil(mean + max(fixed_buffer, 0.20 * mean)))


def sample_industrial_lead_days(mean: float, rng: random.Random) -> float:
    """
    Industrial lead-time approximation without historical PO data.
    Most orders arrive on the supplier reference lead time. A small portion is
    early or late, and a very small right tail models supplier/logistics delays.
    """
    reference = int(round(max(1.0, mean)))
    early_window = max(1, int(round(min(7.0, max(1.0, 0.08 * reference)))))
    late_window = max(1, int(round(min(10.0, max(2.0, 0.10 * reference)))))
    draw = rng.random()
    if draw < 0.72:
        return float(reference)
    if draw < 0.85:
        early_delta = max(1, int(round(rng.triangular(1, early_window, 1))))
        return float(max(1, reference - early_delta))
    if draw < 0.97:
        late_delta = max(1, int(round(rng.triangular(1, late_window, 1))))
        return float(reference + late_delta)

    tail_cap = max(late_window + 1, int(round(min(21.0, max(4.0, 0.18 * reference)))))
    late_tail = max(late_window + 1, int(round(rng.triangular(late_window + 1, tail_cap, late_window + 1))))
    return float(reference + late_tail)


def sample_lead_days(
    lane: dict[str, Any],
    rng: random.Random,
    stochastic: bool,
    distribution_mode: str = "erlang",
) -> int:
    if "physical_transport_days" in lane:
        # Explicit internal transport scenario; the FIA procurement reference
        # and its stochastic distribution are not a physical travel-time law.
        return lane["physical_transport_days"]
    deterministic = int(round(max(1.0, to_float(lane.get("lead_days"), 1.0))))
    if not stochastic:
        return deterministic

    mean = max(1.0, to_float(lane.get("lead_days_mean"), deterministic))
    stages = int(round(max(1.0, to_float(lane.get("lead_stages"), 1.0))))
    lt_type = str(lane.get("lead_time_type", "constant")).lower()
    distribution_mode = normalize_lead_time_distribution_mode(distribution_mode)

    sampled = mean
    if distribution_mode == "industrial" and "constant" not in lt_type:
        sampled = sample_industrial_lead_days(mean, rng)
    elif "erlang" in lt_type:
        sampled = rng.gammavariate(stages, mean / stages)
    elif "constant" not in lt_type:
        sigma = max(0.25, 0.30 * mean)
        sampled = rng.gauss(mean, sigma)

    sampled_days = int(max(1, math.ceil(sampled)))
    delay_limit = int(round(max(1.0, to_float(lane.get("delay_step_limit"), 999.0))))
    return min(sampled_days, delay_limit)


def supplier_delivery_lead_days(
    lane: dict[str, Any], rng: random.Random | None, *, mode: str,
    stochastic: bool, distribution_mode: str = "erlang",
) -> int:
    """Execute one FIA supplier delivery, independently of coverage sizing.

    FIA days retain the current calendar-day assumption. Receipt/availability
    days are applied separately by the caller. The historical branch delegates
    unchanged; the source branch never reads or advances a random stream.
    """
    if mode == "sampled":
        return sample_lead_days(lane, rng, stochastic, distribution_mode)
    if mode != "source":
        raise ValueError("Supplier delivery mode must be sampled or source")
    value = lane.get("lead_days_mean")
    if (lane.get("lead_time_source") != "case_data_fia" or lane.get("lead_time_is_default")
            or isinstance(value, bool) or not isinstance(value, (int, float))
            or not math.isfinite(value) or value <= 0 or float(value) != int(value)):
        raise ValueError("Source supplier delivery requires an explicit positive whole-day FIA reference")
    return int(value)


def resolve_empirical_supplier_delivery_policy(payload, *, origin_date):
    """Validate estimated receipt residuals; never infer order creation dates."""
    if (not isinstance(payload, dict) or type(payload.get("schema_version")) is not int
            or payload["schema_version"] != 1 or payload.get("origin_date") != origin_date
            or type(payload.get("min_samples")) is not int or payload["min_samples"] < 5
            or not isinstance(payload.get("observations"), list)):
        raise ValueError("Empirical deliveries require an explicit dated calibration with at least five samples")
    identities = set()
    for row in payload["observations"]:
        if not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]:
            raise ValueError("Empirical observation requires an identity")
        if row["id"] in identities:
            raise ValueError("Duplicate empirical observation")
        identities.add(row["id"])
        if any(type(row.get(k)) is not int for k in ("known_day", "delta_days", "lower_days", "upper_days")):
            raise ValueError("Empirical days must be finite integers")
        if row["known_day"] < 0 or not row["lower_days"] <= row["delta_days"] <= row["upper_days"]:
            raise ValueError("Invalid empirical observation interval")
        if "observed_end_day" in row and (type(row["observed_end_day"]) is not int
                or row["known_day"] < row["observed_end_day"]):
            raise ValueError("Empirical observation cannot be known before its closing photo")
    return payload


def empirical_supplier_delivery_draw(lane, rng, *, policy, decision_day, stochastic):
    """FIA plus one estimated residual, sampled only from already known photos.

    The midpoint represents a censored weekly interval, not a measured exact
    supplier delay. Sparse history uses FIA deterministically, never Erlang.
    """
    if type(decision_day) is not int or decision_day < 0:
        raise ValueError("Empirical delivery decision day must be a nonnegative integer")
    reference = supplier_delivery_lead_days(lane, None, mode="source", stochastic=False)
    eligible = [r for r in policy["observations"] if r["known_day"] <= decision_day]
    evidence = {"empirical_sample_id": "", "empirical_known_day": "",
                "empirical_pool_size": len(eligible), "empirical_delta_days": 0,
                "empirical_unclipped_lead_days": reference,
                "empirical_status": "deterministic" if not stochastic else "fallback_insufficient_history"}
    if not stochastic or len(eligible) < policy["min_samples"]:
        return reference, evidence
    sample = eligible[rng.randrange(len(eligible))]
    raw_lead = reference + sample["delta_days"]
    evidence.update(empirical_sample_id=sample["id"], empirical_known_day=sample["known_day"],
                    empirical_delta_days=sample["delta_days"], empirical_unclipped_lead_days=raw_lead,
                    empirical_status="sampled_clipped_at_one_day" if raw_lead < 1 else "sampled")
    return max(1, raw_lead), evidence


def compose_controlled_lane_lead_days(
    *,
    transport_lead_days_before_quality: float,
    quality_delay_days: float,
    expedite_level: float = 0.0,
    lead_time_adjustment_days: int = 0,
    delay_control_active: bool = False,
) -> int:
    """Compose transport control and an independent quality-release hold.

    Expediting and manual lead-time adjustments are transport levers.  They
    must not shorten a quarantine or any other quality-release delay.  The
    inactive branch deliberately retains the historical single-ceiling
    calculation so a neutral schedule remains byte-for-byte compatible with
    the pre-control lead-time behavior, including fractional risk inputs.
    """

    transport_before_quality = max(
        0.0,
        float(transport_lead_days_before_quality),
    )
    quality_hold = max(0.0, float(quality_delay_days))
    if not delay_control_active:
        return max(
            1,
            int(math.ceil(transport_before_quality + quality_hold)),
        )

    transport_days = max(1, int(math.ceil(transport_before_quality)))
    expedite_reduction = int(
        math.floor(
            max(0.0, float(expedite_level))
            * max(0, transport_days - 1)
        )
    )
    controlled_transport_days = max(
        1,
        transport_days
        + int(lead_time_adjustment_days)
        - expedite_reduction,
    )
    # Quality delays are expressed in whole simulation days.  Ceiling them
    # separately guarantees that the complete release hold survives the
    # transport intervention.
    quality_hold_days = max(0, int(math.ceil(quality_hold)))
    return controlled_transport_days + quality_hold_days


def lead_time_reference_days(lane: dict[str, Any]) -> int:
    return int(round(max(1.0, to_float(lane.get("lead_days_mean"), lane.get("lead_days", 1.0)))))


def operational_transport_days(lane: dict[str, Any]) -> int:
    """Planning transport only; receipt processing is applied separately."""
    return lane.get("physical_transport_days", lead_time_reference_days(lane))


def lead_time_cover_days(
    lane: dict[str, Any],
    stochastic: bool,
    distribution_mode: str = "erlang",
) -> int:
    """
    Return conservative lead-time coverage in days for stock sizing.
    With stochastic lead-times, use an approximate p95.
    """
    if "physical_transport_days" in lane:
        return lane["physical_transport_days"]
    mean = max(1.0, to_float(lane.get("lead_days_mean"), lane.get("lead_days", 1.0)))
    if not stochastic:
        cover = int(round(max(1.0, to_float(lane.get("lead_days"), mean))))
    else:
        stages = max(1.0, to_float(lane.get("lead_stages"), 1.0))
        lt_type = str(lane.get("lead_time_type", "constant")).lower()
        distribution_mode = normalize_lead_time_distribution_mode(distribution_mode)
        if distribution_mode == "industrial" and "constant" not in lt_type:
            cover = industrial_lead_cover_days(mean)
        elif "erlang" in lt_type:
            # Erlang(k, theta): sd = mean / sqrt(k)
            sd = mean / math.sqrt(stages)
            cover = int(math.ceil(mean + 1.65 * sd))
        elif "constant" in lt_type:
            sd = 0.0
            cover = int(math.ceil(mean + 1.65 * sd))
        else:
            # Fallback dispersion used in sampling branch.
            sd = max(0.25, 0.30 * mean)
            cover = int(math.ceil(mean + 1.65 * sd))
    delay_limit = int(round(max(1.0, to_float(lane.get("delay_step_limit"), 999.0))))
    return max(1, min(cover, delay_limit))


def propagate_demand_rates(
    demand_target_daily: dict[tuple[str, str], float],
    lanes: list[dict[str, Any]],
) -> dict[tuple[str, str], float]:
    """
    Propagate customer demand signal upstream on same-item transport flows.
    """
    upstream: dict[tuple[str, str], list[tuple[str, str]]] = defaultdict(list)
    for lane in lanes:
        src_pair = (str(lane["src"]), str(lane["item_id"]))
        dst_pair = (str(lane["dst"]), str(lane["item_id"]))
        upstream[dst_pair].append(src_pair)

    signal: dict[tuple[str, str], float] = defaultdict(float)
    queue: deque[tuple[str, str]] = deque()
    for pair, val in demand_target_daily.items():
        d0 = max(0.0, to_float(val, 0.0))
        if d0 <= 0:
            continue
        if d0 > signal[pair]:
            signal[pair] = d0
            queue.append(pair)

    while queue:
        dst_pair = queue.popleft()
        d0 = signal[dst_pair]
        for src_pair in upstream.get(dst_pair, []):
            if d0 > signal[src_pair] + 1e-9:
                signal[src_pair] = d0
                queue.append(src_pair)

    return dict(signal)


def build_process_input_requirements_by_output_pair(
    nodes: list[dict[str, Any]],
    item_unit_map: dict[str, str],
) -> dict[tuple[str, str], list[tuple[tuple[str, str], float]]]:
    requirements: dict[tuple[str, str], list[tuple[tuple[str, str], float]]] = defaultdict(list)
    for node in nodes:
        node_id = str(node.get("id"))
        for proc in node.get("processes") or []:
            batch_size = to_float(proc.get("batch_size"), 1000.0)
            if batch_size <= 0:
                batch_size = 1000.0
            output_items = [
                str((out or {}).get("item_id"))
                for out in (proc.get("outputs") or [])
                if (out or {}).get("item_id") is not None
            ]
            if not output_items:
                continue
            input_requirements: list[tuple[tuple[str, str], float]] = []
            for inp in proc.get("inputs") or []:
                in_item = str((inp or {}).get("item_id"))
                if not in_item:
                    continue
                ratio = to_float((inp or {}).get("ratio_per_batch"), 0.0)
                if ratio <= 0:
                    continue
                input_unit = normalize_unit((inp or {}).get("ratio_unit"))
                item_unit = normalize_unit(item_unit_map.get(in_item, input_unit))
                req_per_output_unit = convert_quantity(ratio / batch_size, input_unit, item_unit)
                if req_per_output_unit > 0:
                    input_requirements.append(((node_id, in_item), req_per_output_unit))
            if not input_requirements:
                continue
            for out_item in output_items:
                requirements[(node_id, out_item)].extend(input_requirements)
    return dict(requirements)


def propagate_supply_demand_rates(
    demand_target_daily: dict[tuple[str, str], float],
    lanes: list[dict[str, Any]],
    process_input_requirements_by_output_pair: dict[tuple[str, str], list[tuple[tuple[str, str], float]]],
) -> dict[tuple[str, str], float]:
    """
    Propagate demand upstream through same-item transport flows and through production BOMs.

    This is used for MRP sizing: a finished-good demand signal creates component
    requirements at the producing site, then those component requirements propagate
    to upstream suppliers on the corresponding item transport flows.
    """
    adjacency: dict[tuple[str, str], list[tuple[tuple[str, str], float]]] = defaultdict(list)
    for lane in lanes:
        src_pair = (str(lane["src"]), str(lane["item_id"]))
        dst_pair = (str(lane["dst"]), str(lane["item_id"]))
        adjacency[dst_pair].append((src_pair, 1.0))
    for output_pair, input_reqs in process_input_requirements_by_output_pair.items():
        for input_pair, req_per_output_unit in input_reqs:
            if req_per_output_unit > 0:
                adjacency[output_pair].append((input_pair, req_per_output_unit))

    signal: dict[tuple[str, str], float] = defaultdict(float)
    propagated_by_edge: dict[tuple[tuple[str, str], tuple[str, str], float], float] = defaultdict(float)
    queue: deque[tuple[str, str]] = deque()
    for pair, val in demand_target_daily.items():
        qty = max(0.0, to_float(val, 0.0))
        if qty <= 0:
            continue
        signal[pair] += qty
        queue.append(pair)

    guard = 0
    guard_limit = max(1000, 20 * (len(adjacency) + sum(len(v) for v in adjacency.values()) + 1))
    while queue:
        guard += 1
        if guard > guard_limit:
            break
        pair = queue.popleft()
        source_qty = signal.get(pair, 0.0)
        if source_qty <= 0:
            continue
        for upstream_pair, multiplier in adjacency.get(pair, []):
            if multiplier <= 0:
                continue
            edge_key = (pair, upstream_pair, round(multiplier, 12))
            already_propagated = propagated_by_edge.get(edge_key, 0.0)
            delta = source_qty - already_propagated
            if delta <= 1e-9:
                continue
            propagated_by_edge[edge_key] = source_qty
            signal[upstream_pair] += delta * multiplier
            queue.append(upstream_pair)

    return dict(signal)


def upstream_external_production_signals(
    external_daily_by_pair: Mapping, *, lanes: list,
    process_input_requirements_by_output_pair: Mapping,
    finished_good_item_ids: set,
) -> dict:
    """Propagate extra uses only upstream, and return intermediate output rates.

    This signal is for physical SD production, not another MPS demand seed.
    The dated purchase plan already contains the same external requirements.
    Multi-source shares sum to one, so one demand is never copied to every source.
    """
    if any(isinstance(qty, bool) or not isinstance(qty, (int, float))
           or not math.isfinite(qty) or qty < 0 for qty in external_daily_by_pair.values()):
        raise ValueError("External production signals must be finite nonnegative quantities")
    incoming: dict = defaultdict(list)
    for lane in lanes:
        pair = (str(lane["dst"]), str(lane["item_id"]))
        raw_share = lane.get("mrp_share", 0.0)
        if isinstance(raw_share, bool) or not isinstance(raw_share, (int, float)) or not math.isfinite(raw_share) or raw_share < 0:
            raise ValueError("External production source shares must be finite and nonnegative")
        incoming[pair].append(((str(lane["src"]), pair[1]), raw_share))
    links = {pair: list(rows) for pair, rows in process_input_requirements_by_output_pair.items()}
    for pair, sources in incoming.items():
        if links.get(pair):
            raise ValueError("External output cannot both manufacture and buy without explicit sourcing split")
        total = math.fsum(share for _, share in sources)
        links[pair] = [(source, share / total if total else 1.0 / len(sources)) for source, share in sources]
    nodes = set(links) | set(external_daily_by_pair)
    for sources in links.values():
        for source, weight in sources:
            if isinstance(weight, bool) or not isinstance(weight, (int, float)) or not math.isfinite(weight) or weight < 0:
                raise ValueError("External production coefficients must be finite and nonnegative")
            nodes.add(source)
    indegree = {pair: 0 for pair in nodes}
    for sources in links.values():
        for source, _ in sources:
            indegree[source] += 1
    ready = deque(sorted(pair for pair in nodes if not indegree[pair]))
    signal = defaultdict(float, external_daily_by_pair)
    visited = 0
    while ready:
        pair = ready.popleft()
        visited += 1
        for source, weight in links.get(pair, ()):
            signal[source] += signal[pair] * weight
            indegree[source] -= 1
            if not indegree[source]:
                ready.append(source)
    if visited != len(nodes):
        raise ValueError("External production propagation requires an acyclic network")
    return {pair: signal[pair] for pair in process_input_requirements_by_output_pair
            if pair[1] not in finished_good_item_ids and signal[pair] > 0}


def lotified_mps_component_signal(
    output_demand_signal: dict[tuple[str, str], float],
    *,
    day: int,
    process_input_requirements_by_output_pair: dict[tuple[str, str], list[tuple[tuple[str, str], float]]],
    production_lot_policy_by_pair: dict[tuple[str, str], dict[str, Any]],
    process_capacity_by_output_pair: dict[tuple[str, str], float],
    mps_open_campaign_qty_by_pair: dict[tuple[str, str], float],
    mps_started_lots_by_week_pair: dict[tuple[int, tuple[str, str]], int],
    expand_internal_outputs: bool = True,
    closed_output_pairs: set | None = None,
) -> tuple[dict[tuple[str, str], float], dict[tuple[str, str], float]]:
    """
    Build component demand from a lotified master production schedule.

    The input is the output demand seen by production nodes. For each produced
    output, this function applies the same lot/campaign rules used by execution,
    then explodes the planned production through the BOM. If an input is itself
    produced internally, its requirement is queued as a demand for that upstream
    process before non-produced component demand is returned. When the caller
    already supplies a complete program for every output, disabling expansion
    prevents counting the same intermediate program twice.
    """
    component_signal: dict[tuple[str, str], float] = defaultdict(float)
    planned_output_signal: dict[tuple[str, str], float] = defaultdict(float)
    pending: deque[tuple[str, str]] = deque()
    pending_qty: dict[tuple[str, str], float] = defaultdict(float)
    produced_pairs = set(process_input_requirements_by_output_pair)
    for pair, qty in output_demand_signal.items():
        qty = max(0.0, to_float(qty, 0.0))
        if qty <= 1e-9:
            continue
        pending_qty[pair] += qty
        pending.append(pair)

    guard = 0
    guard_limit = max(1000, 10 * (len(produced_pairs) + len(output_demand_signal) + 1))
    while pending:
        guard += 1
        if guard > guard_limit:
            break
        out_pair = pending.popleft()
        required_qty = pending_qty.pop(out_pair, 0.0)
        if out_pair in (closed_output_pairs or ()):
            continue
        if required_qty <= 1e-9:
            continue
        input_requirements = process_input_requirements_by_output_pair.get(out_pair)
        if not input_requirements:
            continue

        lot_policy = production_lot_policy_by_pair.get(out_pair, {"enabled": False})
        cap_qty = max(0.0, process_capacity_by_output_pair.get(out_pair, 0.0))
        campaign_remaining_start_qty = max(0.0, mps_open_campaign_qty_by_pair.get(out_pair, 0.0))
        planned_qty = required_qty
        week_index = int(day // 7)
        week_key = (week_index, out_pair)
        if lot_policy.get("enabled"):
            if campaign_remaining_start_qty <= 1e-9 and required_qty > 1e-9:
                campaign_requested_qty = launch_campaign_qty(required_qty, lot_policy)
                campaign_started_qty = campaign_requested_qty
                weekly_lot_limit = max(0, int(math.floor(to_float(lot_policy.get("max_lots_per_week"), 0.0))))
                if weekly_lot_limit > 0:
                    started_lots = int(mps_started_lots_by_week_pair.get(week_key, 0))
                    available_lots = max(0, weekly_lot_limit - started_lots)
                    campaign_started_qty = limit_campaign_qty_by_weekly_lots(
                        campaign_requested_qty,
                        lot_policy,
                        available_lots,
                    )
                    mps_started_lots_by_week_pair[week_key] = (
                        started_lots + campaign_lot_count(campaign_started_qty, lot_policy)
                    )
                campaign_remaining_start_qty = campaign_started_qty
                mps_open_campaign_qty_by_pair[out_pair] = campaign_started_qty
            planned_qty = campaign_remaining_start_qty

        if cap_qty > 1e-9:
            planned_qty = min(planned_qty, cap_qty)
        planned_qty = max(0.0, planned_qty)
        if planned_qty <= 1e-9:
            continue
        if lot_policy.get("enabled"):
            mps_open_campaign_qty_by_pair[out_pair] = max(0.0, campaign_remaining_start_qty - planned_qty)

        planned_output_signal[out_pair] += planned_qty
        for input_pair, req_per_output_unit in input_requirements:
            input_qty = planned_qty * max(0.0, req_per_output_unit)
            if input_qty <= 1e-9:
                continue
            if expand_internal_outputs and input_pair in produced_pairs:
                pending_qty[input_pair] += input_qty
                pending.append(input_pair)
            else:
                component_signal[input_pair] += input_qty

    return dict(component_signal), dict(planned_output_signal)


def pair_label(node_id: str, item_id: str) -> str:
    return f"{node_id} | {item_id}"


def scenario_policy_value(scenario: dict[str, Any], key: str, default: float) -> float:
    raw = scenario.get(key, None)
    if raw is None:
        policy = scenario.get("inventory_policy") or {}
        raw = policy.get(key, None)
    return to_float(raw, default)


def scenario_policy_bool(scenario: dict[str, Any], key: str, default: bool) -> bool:
    raw = scenario.get(key, None)
    if raw is None:
        policy = scenario.get("inventory_policy") or {}
        raw = policy.get(key, None)
    if raw is None:
        return default
    if isinstance(raw, bool):
        return raw
    return str(raw).strip().lower() in {"1", "true", "yes", "y", "on"}


def scenario_policy_dict(scenario: dict[str, Any], key: str) -> dict[str, Any]:
    raw = scenario.get(key, None)
    if raw is None:
        policy = scenario.get("inventory_policy") or {}
        raw = policy.get(key, None)
    return raw if isinstance(raw, dict) else {}


def normalize_policy_item_id(item_id: str) -> str:
    item_id = str(item_id).strip()
    return item_id if item_id.startswith("item:") else f"item:{item_id}"


def policy_pair_key(node_id: str, item_id: str) -> str:
    return f"{str(node_id).strip()}|{normalize_policy_item_id(item_id)}"


def parse_pair_factor_map(raw: Any) -> dict[str, float]:
    if not isinstance(raw, dict):
        return {}
    parsed: dict[str, float] = {}
    for raw_key, raw_value in raw.items():
        factor = to_float(raw_value, float("nan"))
        if not math.isfinite(factor):
            continue
        factor = max(0.0, min(10.0, factor))
        key = str(raw_key).strip()
        parts: list[str]
        if "|" in key:
            parts = [part.strip() for part in key.split("|", 1)]
        elif "/" in key:
            parts = [part.strip() for part in key.split("/", 1)]
        elif "," in key:
            parts = [part.strip() for part in key.split(",", 1)]
        else:
            continue
        if len(parts) != 2 or not parts[0] or not parts[1]:
            continue
        parsed[policy_pair_key(parts[0], parts[1])] = factor
    return parsed


def parse_pair_factor_specs(specs: list[str]) -> dict[str, float]:
    parsed: dict[str, float] = {}
    for spec in specs or []:
        text = str(spec).strip()
        if not text:
            continue
        if "=" in text:
            pair_text, factor_text = text.rsplit("=", 1)
            if "|" in pair_text:
                node_id, item_id = [part.strip() for part in pair_text.split("|", 1)]
            elif "/" in pair_text:
                node_id, item_id = [part.strip() for part in pair_text.split("/", 1)]
            elif "," in pair_text:
                node_id, item_id = [part.strip() for part in pair_text.split(",", 1)]
            else:
                continue
        else:
            parts = [part.strip() for part in text.split(",")]
            if len(parts) != 3:
                continue
            node_id, item_id, factor_text = parts
        if not node_id or not item_id:
            continue
        factor = to_float(factor_text, float("nan"))
        if not math.isfinite(factor):
            continue
        parsed[policy_pair_key(node_id, item_id)] = max(0.0, min(10.0, factor))
    return parsed


def parse_pair_key_values(raw: Any) -> list[str]:
    if raw is None:
        return []
    if isinstance(raw, dict):
        values = list(raw.keys())
    elif isinstance(raw, (list, tuple, set)):
        values = list(raw)
    else:
        values = [raw]
    parsed: set[str] = set()
    for value in values:
        text = str(value).strip()
        if not text:
            continue
        if "|" in text:
            parts = [part.strip() for part in text.split("|", 1)]
        elif "/" in text:
            parts = [part.strip() for part in text.split("/", 1)]
        elif "," in text:
            parts = [part.strip() for part in text.split(",", 1)]
        else:
            continue
        if len(parts) != 2 or not parts[0] or not parts[1]:
            continue
        parsed.add(policy_pair_key(parts[0], parts[1]))
    return sorted(parsed)


def resolve_mrp_requirement_pair_modes(
    inherited_static_pairs: Any,
    cli_static_pairs: Any,
    cli_dynamic_pairs: Any,
) -> tuple[list[str], list[str]]:
    """Resolve additive static requests and targeted dynamic overrides."""

    static_pairs = set(parse_pair_key_values(inherited_static_pairs))
    static_pairs.update(parse_pair_key_values(cli_static_pairs))
    dynamic_pairs = set(parse_pair_key_values(cli_dynamic_pairs))
    static_pairs.difference_update(dynamic_pairs)
    return sorted(static_pairs), sorted(dynamic_pairs)


def normalize_optional_item_id(item_id: Any) -> str:
    text = str(item_id or "").strip()
    if not text or text == "*":
        return ""
    return text if text.startswith("item:") else f"item:{text}"


